package com.phoenix.business.domain;
import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="members") @Getter @Setter @NoArgsConstructor
public class Member { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="member_code",nullable=false,unique=true) private String memberCode; @Column(nullable=false) private String name; @Column(unique=true) private String phone; @Column(unique=true) private String email; private String gender; @Column(name="date_of_birth") private LocalDate dateOfBirth; private String address; @Column(name="emergency_contact") private String emergencyContact; @Column(name="join_date",nullable=false) private LocalDate joinDate; @ManyToOne @JoinColumn(name="plan_id") private MembershipPlan plan; @Column(name="membership_start_date") private LocalDate membershipStartDate; @Column(name="expiry_date") private LocalDate expiryDate; @Enumerated(EnumType.STRING) @Column(nullable=false) private Status status=Status.ACTIVE; @Column(nullable=false) private boolean archived=false; @Column(name="photo_data",columnDefinition="LONGTEXT") private String photoData; private String notes; @Column(name="created_at",insertable=false,updatable=false) private Instant createdAt; @Column(name="updated_at",insertable=false,updatable=false) private Instant updatedAt; public enum Status {ACTIVE,EXPIRED,INACTIVE} }
